const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define coastal regions of Victoria and New South Wales
  const victoria = ee.Geometry.Polygon([
    [[140.96, -39.16], [149.98, -39.16], [149.98, -37.50], [140.96, -37.50], [140.96, -39.16]]
  ]);

  const nsw = ee.Geometry.Polygon([
    [[149.98, -37.50], [153.64, -37.50], [153.64, -28.16], [149.98, -28.16], [149.98, -37.50]]
  ]);

  const region = victoria.union(nsw);

  // Date ranges
  const date1 = '2019-07-24';
  const date2 = '2020-01-01';

  // Use Sentinel-5P CO (carbon monoxide) as smoke proxy
  const col1 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO')
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filterBounds(region)
    .select('CO_column_number_density');

  const col2 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO')
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filterBounds(region)
    .select('CO_column_number_density');

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`July 24, 2019 images: ${size1}`);
  console.log(`January 1, 2020 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('Missing data for one or both dates');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get mean images
  const img1 = col1.mean();
  const img2 = col2.mean();

  // Calculate statistics
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const mean1 = stats1.CO_column_number_density_mean;
  const count1 = stats1.CO_column_number_density_count;
  const mean2 = stats2.CO_column_number_density_mean;
  const count2 = stats2.CO_column_number_density_count;

  console.log(`July 24, 2019 - Mean CO: ${mean1}, Pixels: ${count1}`);
  console.log(`Jan 1, 2020 - Mean CO: ${mean2}, Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean1 === null || mean1 === undefined || mean2 === null || mean2 === undefined) {
    console.log('Calculation returned invalid values');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare: was there MORE smoke on Jan 1, 2020?
  if (mean2 > mean1) {
    console.log(`More smoke on Jan 1, 2020 (${(mean2/mean1).toFixed(2)}x higher CO)`);
    console.log('<answer>A</answer>');
  } else {
    console.log('Less or equal smoke on Jan 1, 2020');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
